TEST(EncodeAPI, SetRoi) {
  static struct {
    vpx_codec_iface_t *iface;
    int ctrl_id;
  } kCodecs[] = {
#if CONFIG_VP8_ENCODER
    { &vpx_codec_vp8_cx_algo, VP8E_SET_ROI_MAP },
#endif
#if CONFIG_VP9_ENCODER
    { &vpx_codec_vp9_cx_algo, VP9E_SET_ROI_MAP },
#endif
  };
  constexpr int kWidth = 64;
  constexpr int kHeight = 64;

  for (const auto &codec : kCodecs) {
    SCOPED_TRACE(vpx_codec_iface_name(codec.iface));
    vpx_codec_ctx_t enc;
    vpx_codec_enc_cfg_t cfg;

    EXPECT_EQ(vpx_codec_enc_config_default(codec.iface, &cfg, 0), VPX_CODEC_OK);
    cfg.g_w = kWidth;
    cfg.g_h = kHeight;
    EXPECT_EQ(vpx_codec_enc_init(&enc, codec.iface, &cfg, 0), VPX_CODEC_OK);

    vpx_roi_map_t roi = {};
    uint8_t roi_map[kWidth * kHeight] = {};
    if (IsVP9(codec.iface)) {
      roi.rows = (cfg.g_w + 7) >> 3;
      roi.cols = (cfg.g_h + 7) >> 3;
    } else {
      roi.rows = (cfg.g_w + 15) >> 4;
      roi.cols = (cfg.g_h + 15) >> 4;
    }
    EXPECT_EQ(vpx_codec_control_(&enc, codec.ctrl_id, &roi), VPX_CODEC_OK);

    roi.roi_map = roi_map;
    // VP8 only. This value isn't range checked.
    roi.static_threshold[1] = 1000;
    roi.static_threshold[2] = UINT_MAX / 2 + 1;
    roi.static_threshold[3] = UINT_MAX;

    for (const auto delta : { -63, -1, 0, 1, 63 }) {
      for (int i = 0; i < 8; ++i) {
        roi.delta_q[i] = delta;
        roi.delta_lf[i] = delta;
        // VP9 only.
        roi.skip[i] ^= 1;
        roi.ref_frame[i] = (roi.ref_frame[i] + 1) % 4;
        EXPECT_EQ(vpx_codec_control_(&enc, codec.ctrl_id, &roi), VPX_CODEC_OK);
      }
    }

    vpx_codec_err_t expected_error;
    for (const auto delta : { -64, 64, INT_MIN, INT_MAX }) {
      expected_error = VPX_CODEC_INVALID_PARAM;
      for (int i = 0; i < 8; ++i) {
        roi.delta_q[i] = delta;
        // The max segment count for VP8 is 4, the remainder of the entries are
        // ignored.
        if (i >= 4 && !IsVP9(codec.iface)) expected_error = VPX_CODEC_OK;

        EXPECT_EQ(vpx_codec_control_(&enc, codec.ctrl_id, &roi), expected_error)
            << "delta_q[" << i << "]: " << delta;
        roi.delta_q[i] = 0;

        roi.delta_lf[i] = delta;
        EXPECT_EQ(vpx_codec_control_(&enc, codec.ctrl_id, &roi), expected_error)
            << "delta_lf[" << i << "]: " << delta;
        roi.delta_lf[i] = 0;
      }
    }

    // VP8 should ignore skip[] and ref_frame[] values.
    expected_error =
        IsVP9(codec.iface) ? VPX_CODEC_INVALID_PARAM : VPX_CODEC_OK;
    for (const auto skip : { -2, 2, INT_MIN, INT_MAX }) {
      for (int i = 0; i < 8; ++i) {
        roi.skip[i] = skip;
        EXPECT_EQ(vpx_codec_control_(&enc, codec.ctrl_id, &roi), expected_error)
            << "skip[" << i << "]: " << skip;
        roi.skip[i] = 0;
      }
    }

    // VP9 allows negative values to be used to disable segmentation.
    for (int ref_frame = -3; ref_frame < 0; ++ref_frame) {
      for (int i = 0; i < 8; ++i) {
        roi.ref_frame[i] = ref_frame;
        EXPECT_EQ(vpx_codec_control_(&enc, codec.ctrl_id, &roi), VPX_CODEC_OK)
            << "ref_frame[" << i << "]: " << ref_frame;
        roi.ref_frame[i] = 0;
      }
    }

    for (const auto ref_frame : { 4, INT_MIN, INT_MAX }) {
      for (int i = 0; i < 8; ++i) {
        roi.ref_frame[i] = ref_frame;
        EXPECT_EQ(vpx_codec_control_(&enc, codec.ctrl_id, &roi), expected_error)
            << "ref_frame[" << i << "]: " << ref_frame;
        roi.ref_frame[i] = 0;
      }
    }

    EXPECT_EQ(vpx_codec_destroy(&enc), VPX_CODEC_OK);
  }
}

#if CONFIG_VP9_ENCODER
// Segment ids in the ROI map must be in [0, MAX_SEGMENTS). vp9_set_roi_map()
// did not validate the map contents, so out-of-range ids were used to index
// segment count arrays on the stack while encoding inter frames.
TEST(EncodeAPI, SetRoiInvalidSegmentIdVp9) {
  constexpr int kWidth = 64;
  constexpr int kHeight = 64;
  constexpr int kRows = (kHeight + 7) >> 3;
  constexpr int kCols = (kWidth + 7) >> 3;
  constexpr uint8_t kMaxSegments = 8;  // MAX_SEGMENTS

  vpx_codec_ctx_t enc;
  vpx_codec_enc_cfg_t cfg;
  ASSERT_EQ(vpx_codec_enc_config_default(vpx_codec_vp9_cx(), &cfg, /*usage=*/0),
            VPX_CODEC_OK);
  cfg.g_w = kWidth;
  cfg.g_h = kHeight;
  cfg.g_lag_in_frames = 0;
  ASSERT_EQ(vpx_codec_enc_init(&enc, vpx_codec_vp9_cx(), &cfg, 0),
            VPX_CODEC_OK);
  ASSERT_EQ(vpx_codec_control(&enc, VP8E_SET_CPUUSED, 5), VPX_CODEC_OK);

  vpx_image_t *const img =
      vpx_img_alloc(nullptr, VPX_IMG_FMT_I420, kWidth, kHeight, 32);
  ASSERT_NE(img, nullptr);
  for (int plane = 0; plane < 3; ++plane) {
    const int w = plane ? kWidth >> 1 : kWidth;
    const int h = plane ? kHeight >> 1 : kHeight;
    uint8_t *row = img->planes[plane];
    for (int y = 0; y < h; ++y) {
      for (int x = 0; x < w; ++x) {
        row[x] = static_cast<uint8_t>((x * 7 + y * 13) & 255);
      }
      row += img->stride[plane];
    }
  }

  vpx_roi_map_t roi = {};
  uint8_t roi_map[kRows * kCols];
  roi.roi_map = roi_map;
  roi.rows = kRows;
  roi.cols = kCols;
  roi.delta_q[0] = -10;  // Enable segmentation.
  // -1 disables the ref frame feature: with 0 the ROI would force intra
  // prediction and the second frame would not exercise an inter frame.
  for (int i = 0; i < 8; ++i) {
    roi.ref_frame[i] = -1;
  }

  // Segment ids out of range must be rejected.
  memset(roi_map, kMaxSegments, sizeof(roi_map));
  EXPECT_EQ(vpx_codec_control(&enc, VP9E_SET_ROI_MAP, &roi),
            VPX_CODEC_INVALID_PARAM);

  // Valid segment ids must be accepted...
  for (size_t i = 0; i < sizeof(roi_map); ++i) {
    roi_map[i] = static_cast<uint8_t>(i % kMaxSegments);
  }
  EXPECT_EQ(vpx_codec_control(&enc, VP9E_SET_ROI_MAP, &roi), VPX_CODEC_OK);

  // ...and encoding a key frame followed by an inter frame with the ROI map
  // enabled must succeed.
  for (int frame = 0; frame < 2; ++frame) {
    ASSERT_EQ(vpx_codec_encode(&enc, img, /*pts=*/frame, /*duration=*/1,
                               /*flags=*/0, VPX_DL_REALTIME),
              VPX_CODEC_OK);
    vpx_codec_iter_t iter = nullptr;
    while (vpx_codec_get_cx_data(&enc, &iter) != nullptr) {
    }
  }

  vpx_img_free(img);
  EXPECT_EQ(vpx_codec_destroy(&enc), VPX_CODEC_OK);

