      ref_frame[2] == 0 && ref_frame[3] == 0 && ref_frame[4] == 0 &&
      ref_frame[5] == 0 && ref_frame[6] == 0 && ref_frame[7] == 0) {
    memset(ref_frame, -1, sizeof(ref_frame));
